INSERT INTO `rushik_product` VALUES (1,'Unimark - Curlex - 250ml','Unimark - Curlex - 250ml','products/agri_acerbic_hd0uTqK.png',500.00,1.00,0,0,6,'Unimark - Curlex - 250ml','Unimark - Curlex - 250ml','unimark'),(3,'Hair Oil','Hair Oil\r\nNature Has Given Us Abundant Natural Oils And Herbs For Healthy And Shiny Hair. We\r\nAt Unilink Believe In Providing Natural Solutions To Your Health & Beauty Problems.\r\nMyristika 12 In 1 Hair Oil Is One Of The Technologically Advanced Hair Oil With\r\nBioactive 12 Cold Pressed Oils. It Is Manufactured At WHO GMP And ISO Facilities.\r\nMyristika 12 In 1 Hair Oil Is Free From Toxic Chemicals Like LLP, Paraben, PABA, Silicon\r\nEtc.','products/PRD_1_41202216842_Hair_Oil_7NRxpnn.png',700.00,1.00,0,0,2,'null','Nature has given us abundant natural oils and herbs for healthy and shiny hair. We at Unilink believe in providing natural solutions to your\r\nhealth & beauty problems. Myristika 12 in 1 hair oil is one of the technologically advanced hair oil with bioactive 12 cold pressed oils. It is\r\nmanufactured at WHO GMP and ISO facilities. Myristika 12 in 1 hair oil is free from toxic chemicals like LLP, Paraben, PABA, Silicon etc.\r\n\r\nINGREDIENTS\r\n\r\n1. Sesame Oil\r\n\r\nProtects hair from harmful UV rays due to Vitamin-E, Vitamin B-complex, and minerals such as magnesium, calcium, phosphorus, and protein.\r\n\r\n2. Olive Oil\r\n\r\nRich in, Vitamin-A, Vitamin-E, and antioxidants. It makes hair soft and reduces dandruff.\r\n\r\n3.Coconut Oil\r\n\r\nIt improves scalp health, fights infections and supports hair growth.\r\n\r\n4. Almond Oil\r\n\r\nHas Omega-3 fatty acids, phospholipids, Vitamin-E and magnesium. Nourishes & strengthens hair and is optimal for treating hair loss as well as\r\ndamaged hair.\r\n\r\n5. Sunflower Oil\r\n\r\nContains high levels of Oleic Acid and Vitamin-A, B, C & E. It makes hair smoother, shinier, healthier & stronger and protects them from harmful\r\nUV rays.\r\n\r\n6. Jojoba Oil\r\n\r\nDue to Vitamin-E it prevents dryness of the scalp, dandruff and increased hair loss.\r\n\r\n7. Avacado Oil\r\n\r\nPromotes hair health and strength. Provides lustrous and silky look.\r\n\r\n8. Flax seed Oil\r\n\r\nAlpha linoleic acid makes hair shaft strong.\r\n\r\n9. Argan Oil\r\n\r\nImportant and acts as conditioner moisturizer.\r\n\r\n10. Rosemary Oil\r\n\r\nHas antidandruff effect\r\n\r\n11. TeaTree Oil\r\n\r\nHas antidandruff and antifungal effect. Useful against itchy scalp.\r\n\r\n12. Wheatgerm Oil\r\n\r\nPromotes hair growth and root revitalizing effect.\r\n\r\nSPECIAL HERBS:\r\n\r\no Bhrimraj- Prevents premature hair greying due to rich protein and ecliptine content.\r\no Methi- Makes hair shiny and promotes hair growth with antidandruff effect.\r\no Amla- Has Vitamin-C that makes hair healthy and shiny.\r\no Jatamansi- Promotes hair growth and reduces stress.\r\no Vetiver- Reduces stress related to insomnia due to essential oils.\r\no Vitamin E - Has antioxidant property and prevents free radical activity.\r\no Biotin - Revitalizes Hair follicles and stops hair fall\r\nBENEFITS\r\n\r\no All 12 oils helps in reducing hair fall\r\no Prevents premature hair greying\r\no Gives healthy and shiny hair\r\no Helpful in alopecia\r\no Reduce stress related to insomnia and hypertension\r\no Reduces dryness and makes hair silky','Myristika'),(4,'Unistic 5 Ltr.','Unistic Is A Sticker / Spreader & A Kind Of Spray Adjacent Or Wetting Agent Spray\r\nAdjacent Can Be Used Synergistically With All Types Of Insecticides, Weedicides,\r\nPesticides Etc To Increase Their Effectiveness.','products/PRD_1_2411202116558_UNISTIC_5_LTR.png',5700.00,5600.00,10,1,6,'Application & Dose :-\r\n\r\nUse on all types of crops\r\n\r\nUse along with any fungicide, pesticides etc.\r\n\r\n5ml in 15 litre of pesticides, fungicide etc .','Details\r\n\r\nUnistic is a sticker / spreader & a kind of spray adjurent or wetting agent spray adjusnt can be used synergistically with all types of insecticides,\r\nweedicides, pesticides etc to increase their effectiveness .\r\n\r\nCompositions:\r\n\r\nNEEM COMPOUNDS\r\n\r\nIONIC & Non IONIC surfactant / emulsifiers\r\n\r\nUnique features & benefits :-\r\n\r\n1. It is very suitable & less wlatile\r\n\r\n2. It sticks to surface of leaves for longer duration of time\r\n\r\n3. Being a bio product is completely harmless to plant\r\n\r\n4. Decreases the quantity of pesticides & increase it effectiveness\r\n\r\n5. Make farming profitable by reduce expenditure on pesticides etc.\r\n\r\n6. Reduces photodecomposition of pesticides','Unimark'),(5,'UniSoil 5 Liter','Details\r\n\r\nUniSoil 5 Liter\r\n\r\nMRP 3750/- | DP 3000/- BV 1350','products/PRD_10_281202318158_5_Litre_3D_-_UniSoil.png',4000.00,3750.00,10,1,6,'UniSoil 5 Liter','Details\r\n\r\nUniSoil 5 Liter\r\n\r\nMRP 3750/- | DP 3000/- BV 1350','Unimark'),(6,'UniSil - 500 ml','UniSil - 500 ml','products/PRD_42_802025163525_UniSil_500_ml.png',700.00,675.00,10,1,6,'DOSE : 15ml - 25ml In 15 Ml Water','UniSil - 500 ml\r\nMakes Silicon Available To Plant In Bioavailable Form\r\n\r\nReduces Biotic & Abiotic Stress On Crops\r\n\r\nEnhances Plants Ability To Resist Metal Toxification\r\n\r\nStrengthens Stems Of Crops So That They Don\'t Collapse Due To Heavy Rain &\r\nWind. Reduces Stem Breakage\r\n\r\nIncrease Resistence Against Fungal Attacks.','Unimark'),(7,'UniRich - 100 ml','UniRich - 100 ml','products/PRDPRDPRDPRD_42424242_802025163919_UniRich_100_ml.png',300.00,250.00,10,1,6,'DOSE : 15ml - 25ml In 15 Ml Water','BENEFITS:\r\n\r\nEnhances Seed Germination. Boosts Root Formation.\r\n\r\nIncreases Yield /Produce\r\n\r\nHelp Plant To Achieve Stronger Resistance\r\n\r\nPromotes Rapid Root & Shoot Development. Promotes Root Mass\r\n\r\nPromotes Flower Blossom & Fruiting\r\n\r\nHelp Plant Endure Environmental Stress\r\n\r\nHelp To Stop Fruit & Flower Dropping','Unimark'),(8,'Unimark WIND - UP 1 LTR.','Wind-Up Is Broad Spectrum Plant Defence Booster And Works As Bio Fungicide And\r\nProtects Crops From Fungal Diseases. It Protects Crops From Recurring Attacks Of\r\nVarious Fungus, Wilt, Moulds, Rusts Etc','products/PRDPRDPRD_424242_802025163745_Wind-Up_1_Lt.png',1500.00,1400.00,10,1,6,'DOSE : Please use 250 ml. per acre of crop.','BENEFITS:\r\n\r\nIt creates thin coat on plants which creates structural barrier that acts as defence mechanism for plants against microbial and fungul infestation.\r\n\r\nActs effectively as prophylactic and preventive on all types of fungus, wilt, moulds rot etc\r\n\r\nIt also helps to leverage metabolites secreted by micro-organism to be used for plant growth and root system development.','Unimark'),(9,'Unimark Uni-Spase 100 ml','Unimark Uni-Spase 100 ml','products/PRD_42_802025162852_UniSpace_100_ml.png',400.00,325.00,10,1,6,'DOSE : 3-5 ml/15 ltr water for foliar application','Details\r\n\r\nSuper Silicon Spreader\r\n\r\nBENEFITS:\r\n\r\nIt is developed to improve the wetting, spreading and penetration of agriculture chemicals, especially herbicides, insecticides, fungicides & plant\r\ngrowth regulators that are water soluble.\r\n\r\nIt reduces the surface tension to a very low level, resulting in a rapid wetting cum spreading on leaves.\r\n\r\nWhen incorporated with agriculture chemicals, near complete coverage of leaf is achieved.\r\n\r\nIt is multifunctional and acts as Sticker, Penetrator, Activator, Spreader and Emulsifier.','Unimark'),(10,'Unimark UniSoil 500ml V2','Unimark UniSoil 500ml V2','products/PRD_10_402025112835_UniSoil_500_ml.png',500.00,450.00,10,1,6,'DOSE: 1 Litre per acre through soil application.','Details\r\n\r\nIt is highly water soluble & can be used for all types of fertigation system & soil injection. It provides organic matter & humus in natural\r\ncontrolled released form to the soil. Manages soil PH. Increases drought resistance.\r\n\r\nHelp in moisture & nutrient retention . Assist in soil wetting.\r\n\r\nPromotes soil structure improvement by stimulating fungi to create a crumb structure for better water & oxygen intake by improved root\r\npenetration. Completely safe & nontoxic & microbe friendly.','Unimark'),(11,'Unimark UniSoil 5 Ltr V2','Unimark UniSoil 5 Ltr V2','products/PRD_10_281202318158_5_Litre_3D_-_UniSoil_NPihc0J.png',5000.00,4250.00,10,1,6,'null','null','Unimark'),(12,'Unimark UniRich 500ML V2','Unimark UniRich 500ML V2','products/_UniRich_500_ml.png',900.00,850.00,10,1,6,'DOSE : 15ml - 25ml in 15 ml water','BENEFITS:\r\n\r\n. Enhances seed germination. Boosts root formation.\r\n\r\n. Increases yield /produce\r\n\r\n. Help plant to achieve stronger resistance\r\n\r\n. Promotes rapid root & shoot development. Promotes root mass\r\n\r\n.\r\n\r\nPromotes flower blossom & fruiting\r\n\r\n.\r\n\r\nHelp plant endure environmental stress\r\n\r\n. Help to stop fruit & flower dropping','Unimark'),(13,'Unimark UNIFERT-P - 1ltr','Phosphate Solubilizing Bacteria (CFU Min 1 X 108 Cell/ML)','products/PRDPRDPRDPRD_42424242_802025162950_K_1_Litre.png',700.00,650.00,10,1,6,'Dose : 1 to 2 Liter per acre or as per crop conditions.','Details\r\n\r\nBENEFITS:\r\n\r\nUNIFERT-P is a liquid bio-fertilizer made of pure culture of naturally occurring soil-borne Phosphorus solubilizing bacteria (PSB).\r\n\r\nWhen applied to the soil, the bacteria multiplies & produces organic acids & converts insoluble inorganic phosphatic compounds in soil into\r\nsoluble form & makes them available to plants.','Unimark'),(14,'Unimark UNIFERT-P - 5ltr','Phosphate Solubilizing Bacteria (CFU Min 1 X 108 Cell/ML)','products/PRD_25_2802023233353_5_Litre_3D_-_Unifirt_P.png',3500.00,3250.00,10,1,6,'null','BENEFITS:\r\n\r\nUNIFERT-P is a liquid bio-fertilizer made of pure culture of naturally occurring soil-borne Phosphorus solubilizing bacteria (PSB).\r\n\r\nWhen applied to the soil, the bacteria multiplies & produces organic acids & converts insoluble inorganic phosphatic compounds in soil into\r\nsoluble form & makes them available to plants.','Unimark'),(15,'Unimark UnipH - 500ml V2','UNIPH Is Specially Developed For Multi-Functional Spray Adjuvant. Which Helps To\r\nAcidify Water, To Make More Penetration, Enhance Spray Performance And Prevent\r\nAlkaline Hydrolysis. It Also Helps To Adjust PH.','products/UniPH_500_ml.png',900.00,850.00,10,1,6,'APPLICATION & DOSE:\r\n\r\nAlways add to spray water before\r\n\r\nAddition of spray components in mixing tank and\r\n\r\nCheck pH of spray solution as per requirement.\r\n\r\nIt never retains any stains over applied area of plant.\r\n\r\nStandard pH 5.5 to 6.5 for spray solution.\r\n\r\n0.5 to 1 ml per liter of Water or as per water condition','UNIPH Is Specially Developed For Multi-Functional Spray Adjuvant. Which Helps To\r\nAcidify Water, To Make More Penetration, Enhance Spray Performance And Prevent\r\nAlkaline Hydrolysis. It Also Helps To Adjust PH.\r\n\r\nCOMPOSITION:\r\n\r\nBuffer Agent(Acidifier)\r\n\r\nStabilizers\r\n\r\nIndicator\r\n\r\nSolvent\r\n\r\nUNIQUE FEATURES & BENEFITS:\r\n\r\nUniPH is specially developed for multi-functional spray adjuvant.\r\n\r\nWhich helps to acidify water.\r\n\r\nTo make more penetration.\r\n\r\nEnhance spray performance.\r\n\r\nPrevent alkaline hydrolysis. It also helps to adjust pH.','Unimark'),(16,'Unimark UniRich 250ML V2','UNIRICH\r\n\r\nSeaweed | Protein | Amino Acids','products/PRDPRDPRDPRDPRDPRD_101010101010_402025111743_UniRich_250_ml.png',500.00,425.00,10,1,6,'DOSE : 15ml - 25ml in 15 ml water','Benifits:\r\n.\r\n\r\nEnhances seed germination. Boosts root formation.\r\n\r\n. Increases yield /produce\r\n\r\n. Help plant to achieve stronger resistance\r\n\r\n.\r\n\r\nPromotes rapid root & shoot development. Promotes root mass\r\n\r\n. Promotes flower blossom & fruiting\r\n\r\n.\r\n\r\nHelp plant endure environmental stress\r\n\r\n.\r\n\r\nHelp to stop fruit & flower dropping','Unimark'),(17,'Unimark UNIFERT-K - 5ltr','Unimark UNIFERT-K - 5ltr\r\nPotash Mobilizing Bacteria (CFU Min 1 X 108 Cell/ML)','products/PRD_25_2802023233319_5_Litre_3D_-_Unifirt_K.png',3500.00,3250.00,10,1,6,'null','UNIFERT-K is a liquid bio-fertilizer made of pure culture of naturally occurring soil borne Potash Mobilizing bacteria (KMB).\r\n\r\nWhen applied to soil, Potash Mobilizing Bacteria helps to mobilize potassium fixed in soil.\r\n\r\nThis mobilize potassium is easily available to the crops.','Unimark'),(18,'Unimark UNIFERT-K - 1ltr','Potash Mobilizing Bacteria (CFU Min 1 X 108 Cell/ML)','products/PRDPRDPRDPRD_42424242_802025162950_K_1_Litre_enSwUCQ.png',700.00,650.00,10,1,6,'Dose : Mix 1 to 2 Lit for foliar / Soil application per acre.','BENEFITS:\r\n\r\nUNIFERT-K is a liquid bio-fertilizer made of pure culture of naturally occurring soil borne Potash Mobilizing bacteria (KMB).\r\n\r\nWhen applied to soil, Potash Mobilizing Bacteria helps to mobilize potassium fixed in soil.\r\n\r\nThis mobilize potassium is easily available to the crops.','Unimark'),(19,'Unimark UNIFERT AZO-N - 5Ltr','Azotobacter Sp. (CFU Min 1 X 108 Cell/ML)','products/PRD_25_2802023233439_5_Litre_3D_-_Unifirt_N.png',3500.00,3250.00,10,1,6,'null','BENEFITS:\r\n\r\nUNIFERT AZO-N when applied to soil multiplies & absorbs the atmospheric nitrogen and fixes the same in the root zone of soil. It helps to plant\r\nfor rapid growth and yield.\r\n\r\nUseful for organic farming.','Unimark'),(20,'Unimark UNIFERT AZO-N - 1Ltr','Azotobacter Sp. (CFU Min 1 X 108 Cell/ML)','products/PRDPRD_4242_802025162926_N_1_Litre.png',700.00,650.00,10,1,6,'Dose : Mix 1 to 2 Lit for foliar / Soil application per acre.','BENEFITS:\r\n\r\nUNIFERT AZO-N when applied to soil multiplies & absorbs the atmospheric nitrogen and fixes the same in the root zone of soil. It helps to plant\r\nfor rapid growth and yield.\r\n\r\nUseful for organic farming.','Unimark'),(21,'Unimark UNI CHARGER - 1 LTR.','Uni-Charger Is A Derived From Microbial Culture Formulation , Which Works As A Plant\r\nGrowth Promoter By Increasing The Content Of Chlorophyll','products/PRDPRD_4242_802025163555_Uni-Charger_1_Litre.png',1300.00,1200.00,10,1,6,'Dosage and Application :\r\n\r\n1) Drip Irrigation : 1 Litre per Acre\r\n\r\n2) Foliar Spray : 1.0 ml per litre of water\r\n\r\n3)DOSE: 1 Litre per acre through soil application.','DESCRIPTION:\r\n\r\nUni-Charger is a derived from microbial culture formulation, which works as a plant growth promoter by increasing the content of chlorophyll,\r\nprotein and nucleic acid in plants and also helps to increase soil productivity by increasing micro flora of soil, enhance the absorption of water\r\nand fertilizer, To improve the drought resistance and cold resistance of the plants. It helps to enhance the disease resistance of the plants, the\r\noverall growth of the plants is good, the colour is green and yield.\r\n\r\nRecommended for :\r\n\r\nSuitable for all crops like Paddy, Wheat, Maize, Groundnut, Sugarcane, Grapes, Pomegranate, Citrus, Banana, Tea, Coffee, Coconut, Vegetables\r\nand Flowers.\r\n\r\nStorage :\r\n\r\nStore in cool and dry place away from direct sunlight and heat.','Unimark'),(22,'Unimark UniCarbN 1Ltr V2','Uni-CarbN Is Biologically Produce Formulation From Natural Resources In Liquid Form\r\nFor Plants.','products/Uni-CarbN_1_Litre.png',1000.00,900.00,10,1,6,'500 ml to 1 liter /acre with sufficient water or depending up on the stage of the crop.','Uni-CarbN is biologically produce formulation from Natural resources in liquid form for plants. The benefits include faster development,\r\nproliferate root growth, abundant blossoming and superior resistance to disease.\r\n\r\nINGREDIENTS:\r\n\r\nIt contains Natural Proteins 16%, Organic Acids 10% and Other Ingredients Q.S.%.\r\n\r\nBENEFITS:\r\n\r\n·It helps to improve mineral uptake through roots and between cells as well as speeding cellular metabolism. Increases buffering\r\n\r\nproperties of soil.\r\n\r\n·Helping Plants to resist drought. Increases root respiration and root formation. Increases germination resulting in to uniform crop.\r\n\r\n.It contains naturally derived aminoacid in the form of proteins.\r\n\r\n·It promotes vegetative growth of differents plant at differents stages.','Unimark'),(23,'Unimark UniCarbN 5Ltr V2','Unimark UniCarbN 5Ltr V2','products/PRD_10_2812023181241_5_Litre_3D_-_UniCarbN.png',5000.00,4500.00,10,1,6,'null','null','Unimark'),(24,'Unimark UniComp 1Ltr V2','Various Micro-Organisms Including Bacillus Sp | Actinomycetes Sp, | Aspergillus Sp |\r\nCellulomonas','products/1_Uni-Comp_1_litre.png',900.00,850.00,10,1,6,'null','Increases humus contents.\r\n\r\nImproves soil texture.\r\n\r\nHigher availability of nutrients.\r\n\r\nImproves water holding capacity.\r\n\r\nProvision of substrate for growing beneficial micro-organisms.\r\n\r\nSustained release of nutrients.','Unimark'),(25,'Unimark Top Soil 1kg','Unimark Top Soil 1kg','products/PRD_10_274202215412_TopSoil_1_kg_1000x1000px.png',900.00,800.00,10,1,6,'DOSE : 2-5 kg per acre','Soil is the most vital substance in farming. It hosts various nutrients, friendly bacteria useful for crop growth an yield. But at the same time Soil\r\nalso hosts a variety of soil insects like White Grubs, Termites and Stem Borers etc. TOP SOIL is a Certified organic input having herbs known in\r\nAyurveda to boost plant immunity against natural attacks of soil borne pests.','Unimark'),(26,'Unimark Sparsh Bio - 1Ltr','SPARSH BIO\r\nMicrobial Broth','products/PRDPRDPRDPRDPRDPRD_424242424242_802025163157_Sparsh_Bio_Bottle_3D.png',1300.00,1200.00,10,1,6,'DOSE : 5 to 10 ml in one litre of water.','Increased Production of Growth Promoting Substances and Growth Factors\r\n\r\nIncreased Chlorophyll Production\r\n\r\nImproved Root Growth\r\n\r\nImproved Shoot Growth\r\n\r\nImproved Seed setting','Unimark'),(27,'Unimark Hook Up -1ltr','HOOK UP Is A Plant Extract Based Tonic. Plant Extracts Added Are Known In Ayurveda\r\nTo Boost Plant Immunity Against Natural Attacks Due To Climate Change On Crops Like\r\nFruits & Vegetables.','products/PRD_10_206202295553_Hook_Up_1_Lt_1000x1000px.png',2100.00,2000.00,10,1,6,'DOSE: 1 Litre per acre through soil application.','UNIQUE FEATURES & BENEFITS:\r\n\r\nHOOK UP is totally safe, herbal and have no residue effects on plants.\r\n\r\nHOOK UP is based on principles of organic management of crops.\r\n\r\nIt also has herbal extract which are known in Ayurveda to boost plant immunity against natural attacks of nematodes due to climate change\r\non crops like fruits & vegetables.','Unimark'),(28,'Unimark Booster 25gm','Booster has been derived from an alkaloid from herbal extract called Jasmonate. It is useful for all types of crops for overall development of crop\r\nat very less dose per acre.','products/PRDPRDPRDPRDPRD_4242424242_802025163116_Booster_3D-01.png',900.00,850.00,10,1,6,'DOSE: 25 gm in 150-200 liters of water per acre for all crops.','Booster is very innovative, comprehensive Growth Promoter developed using advance phyto chemistry.\r\n\r\nBooster has been derived from an alkaloid from herbal extract called Jasmonate. It is useful for all types of crops for overall development of crop\r\nat very less dose per acre.','Unimark'),(29,'Unimark UNISIL - 1 LTR.','Unisil Provides Organic Silicon To Plant In The Form Of Mono-Silk Is Acid & Is Useful In\r\nOverall Growth Of Plants & Help Them To Complete Plant Life Cycle','products/PRDPRDPRDPRDPRDPRDPRD_42424242424242_80202516330_UniSil_1_litre_1.png',1300.00,1200.00,10,1,6,'Applications & Dose :-\r\n\r\nCan be used in monocot and dicot\r\n\r\nVery useful in paddy crops like wheat & rice\r\n\r\nVegetable crops like tomato, cucumber & strawberry etc.\r\n\r\n250ml/ acre\r\n\r\n500 ml for direct soil application\r\n\r\n3ml/1litre foliar spray\r\n\r\nDOSE: 25 gm in 150-200 liters of water per acre for all crops.','Unisil provides organic silicon to plant in the form of mono-silk is acid & is useful in overall growth of plants & help them to complete plant life\r\ncycle.\r\n\r\nComposition :-\r\n\r\nSilicon in form of mono-silicic acid\r\n\r\nUnique feature & benefits\r\n\r\nMakes silicon available to plant in bioavailable form\r\n\r\nReduces biotic & abiotic stress on crops\r\n\r\nEnhances plants ability to resist mefel toxicition\r\n\r\nStrengthens stems of crops so that they don\'t collapse due to heavy rain & wind\r\n\r\nReduces stem breakage\r\n\r\nIncrease resistance against fungal attacks.','Unimark'),(30,'Unimark UniRich 1 Ltr V2','Unirich Is A Concentrated, Comprehensive Plant Growth Promoter. These Product Help\r\nPlants To Achieve Growth In All Stages. It Is Highly Soluble In Water & Provide Good /\r\nSatisfactory Growth Of Crops.','products/PRDPRDPRDPRDPRD_1010101010_402025111628_UniRich_1_litre.png',1750.00,1600.00,10,1,6,'APPLICATION & DOSE:\r\n\r\n. Can be used on all type of crops\r\n\r\n. Can be used during seed treatment, sowing, sprouting, flowering & fruiting stage\r\n\r\n. Can be used when plant is in stressfull condition','Unirich is a concentrated, comprehensive plant growth promoter. These product help plants to achieve growth in all stages. It is highly soluble in\r\nwater & provide good / satisfactory growth of crops.\r\n\r\nCOMPOSITION:\r\n\r\n· 100% organic seaweed\r\n· Organic sargassum\r\n· Naturally derived growth hormones like auxin, cytokinins, gibrellins etc.\r\n. Naturally derived micronutrient\r\n.Protein & amino acids\r\n\r\nUNIQUE FEATURES & BENEFITS:\r\n\r\n. Enhances seed germination\r\n. Boosts root formation\r\n. Increases yield / produce\r\n. Help plant to achieve stronger resistance\r\n. Promotes rapid root & shoot development\r\n. Promotes root mass\r\n. Promotes flower blossom & fruiting','Unimark'),(31,'Unimark UniSoil 1ltr V2','Unisoil Is A Product For Improving Soil Health, Carbon Nitrogen Ratio In Soil, Fertility\r\nCapacity Of Soil.','products/PRDPRDPRDPRDPRDPRDPRDPRD_1010101010101010_402025111835_UniSoil_1_litre.png',900.00,850.00,10,1,6,'DOSE: 1 Litre per acre through soil application','Unisoil is a product for improving soil health, carbon nitrogen ratio in soil, fertility capacity of soil.\r\n\r\nComposition :- Humic acid Fulvic acid Amino acid Organic acid\r\n\r\nUnique feature & benefits :- It is highly water soluble & can be used for all types of fertigation system & soil injection It is stable, efficient &\r\nmanufactures using advance technology It provides organic matter & humus in natural controlled released form to the soil Help in moisture &\r\nnutrient retention. Assist in soil wetting Promotes soil structure improvement by stimulating fungi to create a crumb structure for better water &\r\noxygen intake improved root penetration Completely safe & nontoxic & microbe friendly Taonags soil PH Increases drought resistance\r\nApplication & Dose :- Use at a dilution rote of 1ml/1j litre Apply as fine mist till folige is wet. Do not apply immediately after rainfall & when plant\r\nis in stress.','Unimark'),(32,'UniCarbN 5 Liter','UniCarbN 5 Liter','products/PRD_10_41202516226_5_Litre_3D_-_UniCarbN.png',4500.00,4250.00,10,1,6,'null','null','Unimark'),(33,'Paw Mark VIMIN - 500ml','Paw Mark VIMIN - 500ml','products/PRD_10_1332022143543_Vimin_500_ml_-_800x800_px.png',700.00,650.00,5,1,5,'null','Paw mark vimin is a scientifically balanced formulation of vitamins, minerals and amino acids as a non-antibiotic growth promoter.\r\n\r\nIt Helps to improve: Performance/ hatchability in breeders, egg Production in layers, weight gain in broilers, resistance to infections, and growth\r\nrate.\r\n\r\nIt also Helps to alleviate stress.\r\n\r\nalso helps to maintain normal metabolism.','Chicken'),(34,'Paw Mark AQUA - KLEAR - 250gm','Paw Mark AQUA - KLEAR - 250gm','products/Aqua-Klear_250_gm.png',700.00,600.00,10,1,5,'null','Aqua klear is the friendly way to beautify your AQUA CULTURE ponds. Aqua klear a biological pond clarifier is 100 percent safe for fish. Aqua\r\nklear contains various bacteria and potent Yucca extract which helps to elimate ammonia and relieves stress condition of aquatic animals .. These\r\nbacteria helps to bio degrade sludge available at the bottom of the pond and helps to reduce pathogenic microbial load as well. It prevents\r\nproduction of toxic gases as well in ponds.','Fish'),(35,'Paw Mark AQUA - KLEAR - 500gm','Paw Mark AQUA - KLEAR - 500gm','products/PRD_10_1332022144855_Aqua-Klear_500_gm_-_800x800_px.png',1500.00,1400.00,10,1,5,'null','Aqua klear is the friendly way to beautify your AQUA CULTURE ponds. Aqua klear a biological pond clarifier is 100 percent safe for fish. Aqua\r\nklear contains various bacteria and potent Yucca extract which helps to elimate ammonia and relieves stress condition of aquatic animals .. These\r\nbacteria helps to bio degrade sludge available at the bottom of the pond and helps to reduce pathogenic microbial load as well. It prevents\r\nproduction of toxic gases as well in ponds.','Fish'),(36,'Paw Mark OXY - UP 500gm','Paw Mark OXY - UP 500gm','products/PRD_10_133202214513_Oxy-Up_500_gm_-_800x800_px.png',900.00,800.00,10,1,5,'null','Unfed aqua feed gets decomposed in water and along with waste of fish depletes oxygen level in water which affects fish growth. Oxy-up in\r\ntablet form, helps to increase the oxygen content of the aquarium, ponds in the short term or during fish transport, and for long term in water . It\r\ncan also improve oxygen levels, particularly at warmer times of the year.\r\n\r\nLow Dissolved Oxygen level can reduce growth, feeding and moulting frequency in shrimps and fishes also. It Increases Dissolved Oxygen levels\r\nwithin a short period of time and maintains long duration upto 4-5 days.','Fish'),(37,'Paw Mark TOXIBIND - 500gm','Paw Mark TOXIBIND - 500gm','products/PRD_10_1332022144722_Toxibind_500_gm_-_800x800_px.png',800.00,750.00,10,1,5,'null','Poultry feeds with moisture or rainy periods helps in growth of mycotoxins. Toxibind is a unique herbal Toxin Binder for poultry has super toxin\r\nbinder herb Yucca extract. It improves liver function and is Useful in Weak chickens. It is useful in Diarrhea and Poor Health Condition, It helps to\r\nImproves the chickens Feed Quality to Increases the Production. It has to be added in the chicken feed to reduce the effects of Toxins. It helps to\r\nimprove Egg Production in Poultry Birds. Useful in Fatty Liver. It helps to increase FCR. Its an ideal feed supplement for Poultry, Chicks, Broilers,\r\nLayers, Breeders, Chicken, Growers,','Chicken'),(38,'Paw Mark ACIGUT - 500ml','Paw Mark ACIGUT - 500ml','products/PRD_10_1332022144220_Acigut_500_ml_-_800x800_px.png',600.00,500.00,10,1,5,'null','Poultry Feed always contains higher protein values. Protein has buffer effect which absorbs the acids from intestine, which results in higher pH\r\nof intestine.\r\n\r\nso acigut is A Super Formulation of weak acids which Improves pre condition for digestion and very Efficiently maintains of gastiric PH.','Chicken'),(39,'Paw Mark AFS -500gm','Paw Mark AFS -500gm','products/Protein_Powder_500_gm.jpg',700.00,600.00,10,1,5,'null','Details\r\n\r\nAnimal feed supplement is compressive feed supplement designed in unique way for all\r\n\r\ndomesticated &amp; commercial animal\r\n\r\nUNIQUE POINTS:\r\n\r\nProtein\r\n\r\nVitamins\r\n\r\nMinerals\r\n\r\nPrebiotics\r\n\r\nProbiotics\r\n\r\nBypass Fat\r\n\r\nUNIQUE FEATURES &amp; BENEFITS:\r\n\r\nCows &amp; Buffalos\r\n\r\nIncreases Milk Yield by 10-15% according to breed.\r\n\r\nIncrease SNF and Fat in Milk making Milk more valuable and economical for farmers.\r\n\r\nHelps to attain 1 calf per year. Increases Overall growth of cattle&#39;s. Reduces cattle diseases probablity\r\n\r\nGoats &amp; Sheep\r\n\r\nIncreases weight of goats making them economically more viable. Increases milk yield &amp;\r\n\r\nfertility yield as well.\r\n\r\nHorses\r\n\r\nProvides pre workout energy for races. Provides post work out energy after races.\r\n\r\nIncreases skin coat and hair luster.\r\n\r\nFisheries\r\n\r\nIncrease weight of fishes. Reduces mortality of fishes.\r\n\r\nPoultry\r\n\r\nIncrease weight of poultry by helping them to attain weight in 30 days only making more\r\n\r\neconomical for poultry breeders.\r\n\r\nIncrease Immunity &amp; reduces mortality chances in birds.\r\n\r\nIn case of egg layers, helps to increase protein / albumen content of egg. Provides calcium\r\n\r\nthere by increases strength of egg shell &amp; minimizes breakages.\r\n\r\nDogs &amp; Cats\r\nDogs &amp; Cats\r\n\r\nOverall growth and immunity.\r\n\r\nAPPLICATION &amp; DOSE:\r\n\r\nCattles: 10 - 20 gm per day\r\n\r\nHorses: 10 - 15 gm per day\r\n\r\nDogs/Cats: 5 - 10 gm per day\r\n\r\nGoats/Sheep: 5 - 10 gm per day\r\n\r\nPoultry: 250 gm per ton of feed\r\n\r\n2 gm with 4 liter water\r\n\r\nFisheries: 1 gm per fish per day','Cow'),(40,'Paw Mark TOXI GO - 500gm','Paw Mark TOXI GO - 500gm','products/PRD_10_1332022145337_ToxiGo_500_gm_-_800x800_px.png',300.00,200.00,10,1,5,'null','TOXI GO is a Fish feed which works as toxin remover from ponds. It contains mineral grade zeacon along with probiotic starin of bacteria which\r\nhelps to neutralize ammonia content from pond. Also helps to adsorb toxic gases and helps in overall growth of fish.','Fish'),(41,'Paw Mark PROGEN - 500ml','Paw Mark PROGEN - 500ml','products/PRD_10_133202214402_Progen_500_ml_-_800x800_px.png',700.00,600.00,10,1,5,'null','paw mark progen is a unique formulation of Probiotics which are \'good bacteria\' that help reverse the ratio of good to bad bacteria in digestive\r\nsystem. Paw marks progen plays a vital role in healthy digestion, proper intestinal health, and participate in the body detoxification. This\r\nspecially balanced Probiotic-formula delivers encapsulated 10 billion CFU live organisms per strain to restore healthy gut function, digestion &\r\nmetabolism. Helps broilers stay fit & fine everyday!','Chicken'),(42,'UNYK TANDOORI CHICKEN MASALA 100 GM V2','UNYK TANDOORI CHICKEN MASALA 100\r\nGM V2','products/PRD_10_40202511111_Tandoori_Chicken_Masala_Pouch_3D.png',170.00,1.00,8,1,4,'null','Unyk Tandoori Masala mix is a combination of spices that gives you restaurant-style tandoori (chicken ,paneer, mushroom baby corn) in minutes.\r\n\r\nUnyk Tandoori Masala infuses rich aroma in everything that goes into the Tandoor.\r\n\r\nEnjoy your Barbeque style home made foods','Masala'),(43,'UNYK SAMBHAR MASALA 100 GM V3','UNYK SAMBHAR MASALA 100 GM V3','products/PRDPRDPRDPRD_1111_2212025145555_PRD_10_402025105824_Sambhar_Masala_Pouch_3D.png',150.00,100.00,10,1,4,'null','Sambhar is the heart of South Indian food.\r\n\r\nIt is a mildly tangy and aromatic combination of vegetables, spices and condiments.\r\n\r\nIt pairs well with hot idlis, vadas, poha or steamed rice.\r\n\r\nAdd a teaspoon of Unyk Sambar Masala to enjoy the authentic Sambhar taste like never before.','Masala'),(44,'UNYK PAV BHAJI MASALA 100 GM V3','UNYK PAV BHAJI MASALA 100 GM V3','products/PRD_1_2212025145019_PRD_10_402025104657_Pav_Bhaji_Masala_Pouch_3D.png',150.00,100.00,10,1,4,'null','The most renowned Indian street food is pav bhaji.\r\n\r\nUnyk pav bhaji masala has authentic taste, flavour and aroma, is a perfect blend of all spices and enhances the taste of your dish and gives you\r\nexperience of street food at home.','Masala'),(45,'UNYK RED CHILLI POWDER 200 GM V2','UNYK RED CHILLI POWDER 200 GM V2','products/PRD_10_40202510377_Red_Chilli_Masala_Pouch_200_gm_3D.png',200.00,150.00,10,1,4,'null','Unyk Red Chili Powder is an essential ingredient in Indian cuisine.\r\n\r\nPrepared from dried red chillies, it adds pungency and flavour to dishes.\r\n\r\nIt is also imparts rich red colour to gravy making it more attractive.','Powder'),(46,'UNYK SABJI MASALA 100 GM V2','UNYK SABJI MASALA 100 GM V2','products/PRD_10_402025105944_Sabji_Masala_Pouch_3D.png',150.00,100.00,10,1,4,'null','Unyk Sabzi Masala is spice full combination that enhances the taste of any vegetable dish.\r\n\r\nIt is the secret of making lip-smacking curries, tasty everyday veggies, and special preparations.','Masala'),(47,'UNYK SAMBHAR MASALA 100 GM V2','UNYK SAMBHAR MASALA 100 GM V2','products/PRD_10_402025105824_Sambhar_Masala_Pouch_3D.png',120.00,80.00,10,1,4,'null','Sambhar is the heart of South Indian food.\r\n\r\nIt is a mildly tangy and aromatic combination of vegetables, spices and condiments.\r\n\r\nIt pairs well with hot idlis, vadas, poha or steamed rice.\r\n\r\nAdd a teaspoon of Unyk Sambar Masala to enjoy the authentic Sambhar taste like never before.','Masala'),(48,'UNYK PAV BHAJI MASALA 100 GM V2','UNYK PAV BHAJI MASALA 100 GM V2','products/PRD_10_402025104657_Pav_Bhaji_Masala_Pouch_3D.png',120.00,80.00,10,1,4,'null','The most renowned Indian street food is pav bhaji.\r\n\r\nUnyk pav bhaji masala has authentic taste, flavour and aroma, is a perfect blend of all spices and enhances the taste of your dish and gives you\r\nexperience of street food at home.','Masala'),(49,'UNYK MUTTON MASALA 100 GM V2','UNYK MUTTON MASALA 100 GM V2','products/PRD_10_40202511333_Mutton_Masala_Pouch_3D.png',120.00,100.00,10,1,4,'null','Unyk Meat Masala is a blend of pepper-coriander- chilli based combine that gives a hot taste to non-veg dishes, particularly meat.\r\n\r\nIt enhances texture, taste and flavor of the meat to give you unique experience of meat like never before.','Masala'),(50,'UNYK KITCHEN KING MASALA 100 GM V2','UNYK KITCHEN KING MASALA 100 GM V2','products/PRD_10_40202511823_Kitchen_King_Masala_Pouch_3D.png',120.00,100.00,10,1,4,'null','Made by using organic spices with Cold press technology to keep essential oils intact for aromatic and rich flavour.\r\n\r\nHelps to enhance and make your dish tasty.\r\n\r\nIdeal for all dishes & Easy to use.','Masala'),(51,'UNYK KASHMIRI KESAR','UNYK KASHMIRI KESAR','products/PRD_1_23112021173420_UNYK_KASHMIRI_KESAR.png',500.00,450.00,10,1,4,'null','Saffron Always Known As Royal Ingredient Having Unique Culinary And Medicinal\r\nBenefits Is Every Household Requirement. But Adulteration With Available Market\r\nSaffron Deprives Us Of These Benefits. Now You Can Achieve Remarkable Benefits\r\nFrom Unyk- Kesar Originally Sourced Directly From Kashmir Farms Cultivated With\r\nOrganic Inputs.','Kesar'),(52,'UNYK GARAM MASALA 100 GM V2','UNYK GARAM MASALA 100 GM V2','products/PRDPRDPRD_111_2212025145413_PRD_10_402025105435_Garam_Masala_Pouch_3D.png',120.00,100.00,10,1,4,'null','The secreate ingredient of all recipes is Garam masala.\r\n\r\nA blend of all essential spices that give a varied flavour to your food.\r\n\r\nKitchen is truly incomplete without the box of Garam Masala.\r\n\r\nIt is a combination of roasted spices, powdered together to give rich taste and aroma to your food.','Masala'),(53,'UNYK GARAM MASALA 100 GM V3','UNYK GARAM MASALA 100 GM V3','products/PRDPRDPRD_111_2212025145413_PRD_10_402025105435_Garam_Masala_Pouch_3D_mafq8nv.png',120.00,100.00,10,1,4,'null','The secreate ingredient of all recipes is Garam masala.\r\n\r\nA blend of all essential spices that give a varied flavour to your food.\r\n\r\nKitchen is truly incomplete without the box of Garam Masala.\r\n\r\nIt is a combination of roasted spices, powdered together to give rich taste and aroma to your food.','Masala'),(54,'UNYK KADHAI PANEER MASALA 100 GM','UNYK KADHAI PANEER MASALA 100 GM','products/PRD_10_402025104922_Kadhai_Paneer_Masala_Pouch_3D.png',120.00,100.00,10,1,4,'null','Made from the choicest varieties of herbs & spices, Kadhai Paneer Masala infuses a whole lot of deliciousness & a spark of royalty to your recipe.\r\n\r\nThe unique blend of spices brings out a diffused affluent, creamy aromatic taste in every bite of this dish.\r\n\r\nRelish it with crispy, fresh naan.','Masala'),(55,'UNYK KANDA LASHUN MASALA 100 GM','UNYK KANDA LASHUN MASALA 100 GM','products/PRD_10_402025104453_Kanda_Lasoon_Masala_Pouch_3D.png',100.00,80.00,10,1,4,'null','Unyk Kanda Lasun Masala is all purpose curry-base, composed of the strong, sweet flavour of garlic combined with the sharp taste of onions.\r\n\r\nIt\'s ready-to-use with zero compromises in the aroma and taste','Masala'),(56,'UNYK FISH CURRY MASALA 10